package com.xyz.question_bank_management_system.modules.source.mapper;
import com.xyz.question_bank_management_system.modules.source.entity.SourceChunk; import org.apache.ibatis.annotations.*; import java.util.List;
@Mapper public interface SourceChunkMapper { @Insert({"<script>","INSERT INTO source_chunk(document_id,chunk_index,section_title,page_start,page_end,content,content_hash,token_count,vector_ref,created_at) VALUES","<foreach collection='items' item='i' separator=','>","(#{i.documentId},#{i.chunkIndex},#{i.sectionTitle},#{i.pageStart},#{i.pageEnd},#{i.content},#{i.contentHash},#{i.tokenCount},#{i.vectorRef},NOW(3))","</foreach>","</script>"}) int batchInsert(@Param("items") List<SourceChunk> items); @Select("SELECT * FROM source_chunk WHERE document_id=#{documentId} ORDER BY chunk_index,id") List<SourceChunk> selectByDocumentId(@Param("documentId") Long documentId); @Select("SELECT * FROM source_chunk WHERE id=#{id}") SourceChunk selectById(@Param("id") Long id);
 @Insert("INSERT INTO source_chunk(document_id,chunk_index,section_title,content,content_hash,token_count,created_at) VALUES(#{documentId},#{chunkIndex},#{sectionTitle},#{content},#{contentHash},#{tokenCount},NOW(3))") @Options(useGeneratedKeys=true,keyProperty="id") int insert(SourceChunk value);
 @Select({"<script>","SELECT DISTINCT sc.* FROM source_chunk sc JOIN knowledge_source ks ON ks.source_chunk_id=sc.id WHERE ks.review_status='pass' AND ks.knowledge_point_id IN","<foreach collection='ids' item='id' open='(' close=')' separator=','>","#{id}","</foreach>","ORDER BY ks.confidence DESC,sc.id DESC LIMIT #{limit}","</script>"}) List<SourceChunk> selectEvidenceForKnowledge(@Param("ids")List<Long> ids,@Param("limit")int limit);
}
